function translate(catalogues, language, key, values = {}) {
  const candidate = catalogues[language]?.[key];
  const fallback = catalogues.en[key];
  const message = typeof candidate === 'string' && candidate.trim() ? candidate
    : typeof fallback === 'string' && fallback.trim() ? fallback : key;
  return message.replace(/\{(\w+)\}/g, (token, name) =>
    Object.hasOwn(values, name) ? String(values[name] ?? '') : token);
}
function resolveLanguage(value, languages) {
  const code = String(value || '').toLowerCase().split(/[-_]/)[0];
  return Object.hasOwn(languages, code) ? code : 'en';
}
let language = resolveLanguage(navigator.language, languages);
return { languages, getLanguage: () => language, setLanguage: value => { language = resolveLanguage(value, languages); }, t: (key, values) => translate(catalogues, language, key, values) };
